#include <stdio.h>
#include <stdlib.h>

// Structure to represent a graph
typedef struct {
    int numVertices;
    int** adj;
} Graph;

// Function to create a graph
Graph* createGraph(int vertices) {
    Graph* graph = (Graph*) malloc(sizeof(Graph));
    graph->numVertices = vertices;

    graph->adj = (int**) malloc(vertices * sizeof(int*));

    for (int i = 0; i < vertices; i++) {
        graph->adj[i] = (int*) malloc(vertices * sizeof(int));
    }

    return graph;
}

// Function to add an edge to the graph
void addEdge(Graph* graph, int src, int dest) {
    graph->adj[src][dest] = 1;
}

// Function to perform topological sorting
void topologicalSort(Graph* graph) {
    int* indegree = (int*) malloc(graph->numVertices * sizeof(int));

    for (int i = 0; i < graph->numVertices; i++) {
        indegree[i] = 0;
    }

    for (int i = 0; i < graph->numVertices; i++) {
        for (int j = 0; j < graph->numVertices; j++) {
            if (graph->adj[i][j] == 1) {
                indegree[j]++;
            }
        }
    }

    int* queue = (int*) malloc(graph->numVertices * sizeof(int));
    int rear = -1;
    int front = -1;

    for (int i = 0; i < graph->numVertices; i++) {
        if (indegree[i] == 0) {
            queue[++rear] = i;
            front++;
        }
    }

    while (front <= rear) {
        int node = queue[front++];
        printf("%d ", node);

        for (int i = 0; i < graph->numVertices; i++) {
            if (graph->adj[node][i] == 1) {
                indegree[i]--;
                if (indegree[i] == 0) {
                    queue[++rear] = i;
                }
            }
        }
    }

    free(indegree);
    free(queue);
}

// Function to check for cycles
int isCyclic(Graph* graph) {
    int* visited = (int*) malloc(graph->numVertices * sizeof(int));
    int* recursionStack = (int*) malloc(graph->numVertices * sizeof(int));

    for (int i = 0; i < graph->numVertices; i++) {
        visited[i] = 0;
        recursionStack[i] = 0;
    }

    for (int i = 0; i < graph->numVertices; i++) {
        if (!visited[i]) {
            if (isCyclicUtil(graph, i, visited, recursionStack)) {
                return 1;
            }
        }
    }

    free(visited);
    free(recursionStack);
    return 0;
}

// Utility function for isCyclic
int isCyclicUtil(Graph* graph, int node, int* visited, int* recursionStack) {
    if (recursionStack[node] == 1) {
        return 1;
    }

    if (visited[node] == 1) {
        return 0;
    }

    visited[node] = 1;
    recursionStack[node] = 1;

    for (int i = 0; i < graph->numVertices; i++) {
        if (graph->adj[node][i] == 1) {
            if (isCyclicUtil(graph, i, visited, recursionStack)) {
                return 1;
            }
        }
    }

    recursionStack[node] = 0;
    return 0;
}

int main() {
    int vertices;
    printf("Enter the number of vertices: ");
    scanf("%d", &vertices);

    Graph* graph = createGraph(vertices);

    printf("Enter the number of edges: ");
    int edges;
    scanf("%d", &edges);

    for (int i = 0; i < edges; i++) {
        int src, dest;
        printf("Enter edge %d (%d - %d): ", i + 1, src, dest);
        scanf("%d %d", &src, &dest);
        addEdge(graph, src, dest);
    }

    if (isCyclic(graph)) {
        printf("Graph contains cycle\n");
    } else {
        printf("Graph doesn't contain cycle\n");
        topologicalSort(graph);
    }

    return 0;
}
